"""Triton implementation of ``torch.linalg.tensorinv``.

Semantics
---------
For ``A`` with shape ``(s_0, ..., s_{N-1})`` and ``ind``:
    m = prod(s_0 .. s_{ind-1}), n = prod(s_ind .. s_{N-1})
PyTorch requires ``m == n`` and returns, with ``B = A.reshape(m, n)``,
``X = B^{-1}.reshape(s_ind, ..., s_{N-1}, s_0, ..., s_{ind-1})``.  The output's
flat element order equals ``B^{-1}``'s flat element order, so the whole operator
is one dense ``m x m`` inversion over the logical row-major flat order.

Algorithm
---------
Single-CTA Gauss-Jordan with partial pivoting, but without physical row swaps:
a ``used`` mask excludes already-pivoted rows from the pivot search, so the
implicitly permuted factorisation is equivalent to the swapped one.  After the
loop ``X_t * B = P * diag(v)``, hence ``B^{-1}[j, :] = X_t[p_j, :] / v_j`` which
is applied as a row scatter (``q``) plus a per-row scale, both built with masked
scatter updates (no dynamic register indexing, no ``tl.gather``).

Two tiles (``A_t`` working matrix, ``X_t`` running transform) live in registers,
so there is no global scratch and exactly one kernel launch for ``m <= 64``.
Larger ``m`` uses a blocked Gauss-Jordan over two float32 scratch buffers.
"""

import logging

import torch
import triton
import triton.language as tl

from flag_gems.runtime import torch_device_fn

logger = logging.getLogger(__name__)

# m <= _TENSORINV_BLOCK_MAX uses a single fused kernel holding the whole m x m
# tile (plus identity) in registers; larger m uses a blocked Gauss-Jordan over
# two float32 scratch buffers.
_TENSORINV_BLOCK_MAX = 64
_BIG_BLOCK = 32
_COPY_BLOCK = 1024


def check_inv_input(A, ind):
    """Validate input for tensorinv: ind is strictly positive, A is >=2D, and
    prod(A.shape[:ind]) == prod(A.shape[ind:]). Raises RuntimeError on
    violation, matching torch.linalg.tensorinv's behaviour.
    """
    # Checked first, as in torch: a non-positive ind is rejected before any
    # shape reasoning, so ind=0 cannot slip through to the prod comparison
    # below (which it would satisfy trivially for a 1x1 input, yielding a
    # silently wrong result instead of an error).
    if ind <= 0:
        raise RuntimeError(
            "linalg.tensorinv: Expected a strictly positive integer for "
            f"'ind', but got {ind}"
        )
    if A.dim() < 2:
        raise RuntimeError(
            "linalg.tensorinv: Expected input to be at least 2D, " f"got {A.dim()}D"
        )
    if ind > A.dim():
        raise RuntimeError(
            "linalg.tensorinv: Expected 0 <= ind <= input.dim(), "
            f"got ind={ind} for input.dim()={A.dim()}"
        )
    m = 1
    for i in range(ind):
        m *= A.shape[i]
    n = 1
    for i in range(ind, A.dim()):
        n *= A.shape[i]
    if m != n:
        raise RuntimeError(
            "linalg.tensorinv: Expected self to satisfy the requirement "
            "prod(self.shape[ind:]) == prod(self.shape[:ind]), "
            f"but got {n} != {m}"
        )


@triton.jit
def _gj_invert(a, x, M, rows, cols, BM: tl.constexpr):
    """Implicit-pivot Gauss-Jordan on register tiles.

    ``a`` is the working matrix, ``x`` starts as the identity and accumulates
    the same row operations.  Returns ``(scaled_rows, q)`` where row ``i`` of
    the result belongs to output row ``q[i]`` (already scaled by 1/pivot).
    """
    used = rows >= BM  # all-false bool vector
    q = tl.zeros([BM], dtype=tl.int32)
    scale = tl.zeros([BM], dtype=tl.float32)
    for k in range(0, M):
        # column k of the working matrix
        colk = tl.sum(tl.where(cols[None, :] == k, a, 0.0), axis=1)
        # pivot row: largest magnitude among not-yet-used, non-padded rows
        cand = tl.where(used | (rows >= M), -1.0, tl.abs(colk))
        p = tl.argmax(cand, axis=0)
        v = tl.sum(tl.where(rows == p, colk, 0.0), axis=0)
        # elimination multipliers (zero on the pivot row and padded rows)
        f = tl.where((rows != p) & (rows < M), colk / v, 0.0)
        ra = tl.sum(tl.where(rows[:, None] == p, a, 0.0), axis=0)
        rx = tl.sum(tl.where(rows[:, None] == p, x, 0.0), axis=0)
        a = a - f[:, None] * ra[None, :]
        x = x - f[:, None] * rx[None, :]
        q = tl.where(rows == p, k, q)
        scale = tl.where(rows == p, 1.0 / v, scale)
        used = used | (rows == p)
    return x * scale[:, None], q


@triton.jit(do_not_specialize=["M", "S0", "S1", "OS0", "OS1"])
def _tinv_reg_kernel(A, OUT, M, S0, S1, OS0, OS1, BM: tl.constexpr):
    rows = tl.arange(0, BM)
    cols = tl.arange(0, BM)
    mask = (rows[:, None] < M) & (cols[None, :] < M)
    a = tl.load(A + rows[:, None] * S0 + cols[None, :] * S1, mask=mask, other=0.0).to(
        tl.float32
    )
    x = tl.where(rows[:, None] == cols[None, :], 1.0, 0.0)
    x = tl.where(mask, x, 0.0)
    y, q = _gj_invert(a, x, M, rows, cols, BM)
    dst = q[:, None] * OS0 + cols[None, :] * OS1
    tl.store(OUT + dst, y.to(OUT.dtype.element_ty), mask=mask)


@triton.jit(do_not_specialize=["M", "S0", "S1"])
def _copy_fill_kernel(A, AW, XW, M, S0, S1, BLOCK: tl.constexpr):
    """AW <- A (cast to fp32, honouring strides), XW <- identity."""
    idx = tl.program_id(0) * BLOCK + tl.arange(0, BLOCK)
    mask = idx < M * M
    r = idx // M
    c = idx - r * M
    v = tl.load(A + r * S0 + c * S1, mask=mask, other=0.0).to(tl.float32)
    tl.store(AW + idx, v, mask=mask)
    tl.store(XW + idx, tl.where(r == c, 1.0, 0.0), mask=mask)


@triton.jit(do_not_specialize=["M", "OS0", "OS1"])
def _tinv_blocked_kernel(A, B, OUT, M, OS0, OS1, BLOCK: tl.constexpr):
    """Blocked Gauss-Jordan (single program, global scratch) for large ``m``.

    ``A`` is the fp32 working matrix, ``B`` starts as the identity and becomes
    ``A^{-1}``.  Both are contiguous ``M x M`` buffers.
    """
    for k in range(0, M):
        # --- pivot row: max |A[:, k]| among rows >= k ---
        best_val = tl.full((), -1.0, dtype=tl.float32)
        best_row = tl.full((), 0, dtype=tl.int32)
        for i0 in range(0, M, BLOCK):
            rows = i0 + tl.arange(0, BLOCK)
            col = tl.load(A + rows * M + k, mask=rows < M, other=0.0).to(tl.float32)
            abs_col = tl.where((rows >= k) & (rows < M), tl.abs(col), -1.0)
            tile_max = tl.max(abs_col, axis=0)
            tile_row = tl.min(tl.where(abs_col == tile_max, rows, M), axis=0)
            is_better = tile_max > best_val
            best_row = tl.where(is_better, tile_row, best_row)
            best_val = tl.where(is_better, tile_max, best_val)

        # --- swap rows k and best_row in A and B ---
        for j0 in range(0, M, BLOCK):
            cols = j0 + tl.arange(0, BLOCK)
            cmask = cols < M
            row_k_a = tl.load(A + k * M + cols, mask=cmask, other=0.0)
            row_p_a = tl.load(A + best_row * M + cols, mask=cmask, other=0.0)
            tl.store(A + k * M + cols, row_p_a, mask=cmask)
            tl.store(A + best_row * M + cols, row_k_a, mask=cmask)
            row_k_b = tl.load(B + k * M + cols, mask=cmask, other=0.0)
            row_p_b = tl.load(B + best_row * M + cols, mask=cmask, other=0.0)
            tl.store(B + k * M + cols, row_p_b, mask=cmask)
            tl.store(B + best_row * M + cols, row_k_b, mask=cmask)

        tl.debug_barrier()

        # --- normalise pivot row ---
        pivot = tl.load(A + k * M + k).to(tl.float32)
        for j0 in range(0, M, BLOCK):
            cols = j0 + tl.arange(0, BLOCK)
            cmask = cols < M
            a_row = tl.load(A + k * M + cols, mask=cmask, other=0.0).to(tl.float32)
            b_row = tl.load(B + k * M + cols, mask=cmask, other=0.0).to(tl.float32)
            tl.store(A + k * M + cols, a_row / pivot, mask=cmask)
            tl.store(B + k * M + cols, b_row / pivot, mask=cmask)

        tl.debug_barrier()

        # --- eliminate column k from every other row ---
        for i0 in range(0, M, BLOCK):
            rows = i0 + tl.arange(0, BLOCK)
            rmask = rows < M
            factor = tl.load(A + rows * M + k, mask=rmask, other=0.0).to(tl.float32)
            factor = tl.where(rows != k, factor, 0.0)
            for j0 in range(0, M, BLOCK):
                cols = j0 + tl.arange(0, BLOCK)
                tmask = rmask[:, None] & (cols[None, :] < M)
                u_a = tl.load(A + k * M + cols, mask=cols < M, other=0.0).to(tl.float32)
                u_b = tl.load(B + k * M + cols, mask=cols < M, other=0.0).to(tl.float32)
                tile_a = tl.load(
                    A + rows[:, None] * M + cols[None, :], mask=tmask, other=0.0
                ).to(tl.float32)
                tile_b = tl.load(
                    B + rows[:, None] * M + cols[None, :], mask=tmask, other=0.0
                ).to(tl.float32)
                tile_a = tile_a - factor[:, None] * u_a[None, :]
                tile_b = tile_b - factor[:, None] * u_b[None, :]
                tl.store(A + rows[:, None] * M + cols[None, :], tile_a, mask=tmask)
                tl.store(B + rows[:, None] * M + cols[None, :], tile_b, mask=tmask)

        tl.debug_barrier()

    # --- write B (the inverse) into the strided output ---
    for i0 in range(0, M, BLOCK):
        rows = i0 + tl.arange(0, BLOCK)
        rmask = rows < M
        for j0 in range(0, M, BLOCK):
            cols = j0 + tl.arange(0, BLOCK)
            tmask = rmask[:, None] & (cols[None, :] < M)
            tile = tl.load(B + rows[:, None] * M + cols[None, :], mask=tmask, other=0.0)
            tl.store(
                OUT + rows[:, None] * OS0 + cols[None, :] * OS1,
                tile.to(OUT.dtype.element_ty),
                mask=tmask,
            )


def linalg_tensorinv(A, ind=2, *, out=None):
    """Compute the multiplicative inverse of tensordot.

    Args:
        A: Input tensor with prod(A.shape[:ind]) == prod(A.shape[ind:]).
        ind: Index at which to compute the inverse of tensordot.

    Returns:
        Tensor X such that tensordot(A, X, ind) is the identity matrix, with
        shape A.shape[ind:] + A.shape[:ind].
    """
    logger.debug("GEMS LINALG_TENSORINV")
    check_inv_input(A, ind)

    # tensorinv reduces to a single dense matrix inverse: flatten the first
    # `ind` dims into rows and the rest into cols, both of size matrix_size
    # (validated equal by check_inv_input).
    shape = A.shape
    matrix_size = 1
    for i in range(ind):
        matrix_size *= shape[i]
    output_shape = shape[ind:] + shape[:ind]
    m = matrix_size

    logger.debug(
        f"GEMS linalg_tensorinv: input shape {A.shape}, ind={ind}, "
        f"matrix_size={matrix_size}, output shape {output_shape}"
    )

    os0 = m
    os1 = 1
    if out is None:
        res = torch.empty(output_shape, dtype=A.dtype, device=A.device)
    else:
        res = out
        if res.dim() == 2:
            st = res.stride()
            os0 = st[0]
            os1 = st[1]
        elif not res.is_contiguous():
            res = res.reshape(m, m)
            st = res.stride()
            os0 = st[0]
            os1 = st[1]

    if A.is_contiguous():
        src = A
        s0 = m
        s1 = 1
    else:
        src = A.reshape(m, m)
        st = src.stride()
        s0 = st[0]
        s1 = st[1]

    with torch_device_fn.device(A.device):
        if m <= _TENSORINV_BLOCK_MAX:
            # BM tracks m (to the next power of two); tensorinv is a single
            # matrix with no batch axis, so a small m should not pay for a
            # larger tile.
            bm = max(2, triton.next_power_of_2(m))
            if bm <= 16:
                nw = 1
            elif bm <= 32:
                nw = 4
            else:
                nw = 8
            _tinv_reg_kernel[(1,)](src, res, m, s0, s1, os0, os1, BM=bm, num_warps=nw)
        else:
            aw = torch.empty((m, m), dtype=torch.float32, device=A.device)
            xw = torch.empty((m, m), dtype=torch.float32, device=A.device)
            _copy_fill_kernel[(triton.cdiv(m * m, _COPY_BLOCK),)](
                src, aw, xw, m, s0, s1, BLOCK=_COPY_BLOCK, num_warps=4
            )
            _tinv_blocked_kernel[(1,)](
                aw, xw, res, m, os0, os1, BLOCK=_BIG_BLOCK, num_warps=4
            )

    return res


def linalg_tensorinv_out(A, ind=2, *, out=None):
    """Out-of-place variant of linalg_tensorinv: computes the tensor inverse
    and writes the result into the provided ``out`` tensor."""
    logger.debug("GEMS LINALG_TENSORINV_OUT")
    return linalg_tensorinv(A, ind=ind, out=out)
